# Verified by tests/test_simulate.py (C++ and SciPy periods vs. the exact formula).
"""Simulate the pendulum swing.

Uses the C++ simulator (../cpp/build/pendulum_sim) when it is built, otherwise SciPy.
All arguments are SI units: I [kg m^2] about the axle, M [kg], d [m] axle to centre of mass,
theta0 [rad] start angle.
"""
import logging
import os
import subprocess
from pathlib import Path

import numpy as np
from scipy.integrate import solve_ivp

log = logging.getLogger(__name__)

PY_ROOT = Path(__file__).resolve().parent.parent      # this repo (python/ in the main repo)
CPP_BUILD = PY_ROOT.parent / "cpp" / "build"           # ../cpp/build in the main repo


def find_simulator():
    """Path to the C++ simulator, or None if it isn't built."""
    env = os.environ.get("PENDULUM_SIM")
    if env:
        return Path(env) if Path(env).exists() else None
    for name in ("pendulum_sim", "pendulum_sim.exe", "Release/pendulum_sim.exe"):  # Release/ = Visual Studio
        if (CPP_BUILD / name).exists():
            return CPP_BUILD / name
    return None


def simulate_cpp(I, M, d, theta0, csv_path, g=9.81, damping=0.0, t_end=10.0, dt=1e-4):
    """Run the C++ simulator. Writes t,theta,omega to csv_path and returns the period [s]."""
    exe = find_simulator()
    if exe is None:
        raise FileNotFoundError("C++ simulator not built, see the main README")
    nums = (I, M, d, g, theta0, damping, t_end, dt)
    args = [str(exe), *(repr(float(v)) for v in nums), str(csv_path)]  # float(): NumPy floats would print as np.float64(...)
    out = subprocess.run(args, capture_output=True, text=True, check=True)
    return float(out.stdout.strip().split("=")[1])


def simulate_scipy(I, M, d, theta0, g=9.81, damping=0.0, t_end=10.0):
    """Same model solved with SciPy. Returns (t, theta, period)."""
    k = M * g * d / I
    sol = solve_ivp(lambda t, y: [y[1], -k * np.sin(y[0]) - damping * y[1]],
                    (0.0, t_end), [theta0, 0.0], max_step=1e-3, rtol=1e-10, atol=1e-12)
    t, th = sol.t, sol.y[0]
    i = np.where((th[:-1] < 0) & (th[1:] >= 0))[0]                  # upward zero crossings
    tc = t[i] - th[i] * (t[i + 1] - t[i]) / (th[i + 1] - th[i])     # interpolated crossing times
    return t, th, float(np.mean(np.diff(tc)))


def simulate(I, M, d, theta0, csv_path, **kwargs):
    """Simulate with C++ if available, else SciPy. Returns (period, backend name)."""
    if find_simulator() is not None:
        return simulate_cpp(I, M, d, theta0, csv_path, **kwargs), "C++"
    log.warning("C++ simulator not found, using SciPy fallback")
    kwargs.pop("dt", None)
    t, th, period = simulate_scipy(I, M, d, theta0, **kwargs)
    np.savetxt(csv_path, np.column_stack([t, th]), delimiter=",", header="t,theta", comments="")
    return period, "SciPy"
